<template>
 <AppShell title="个人主页" back>
  <StateView :loading="loading" :error="error" :count="shop?1:0" @retry="load" />
  <template v-if="shop">
   <view class="player-home-head">
    <view class="row identity-row"><GameArt avatar :size="76" :type="shop.avatar" :src="shop.avatar?.startsWith('/')?shop.avatar:''" /><view class="stack flex-1"><text class="player-name">{{shop.nickname}}</text><text class="province">编号 {{shop.userNo}} · IP属地：{{shop.ipProvince||'未知'}}</text><PlayerBadges :shop-status="shop.shopStatus" :realname-status="shop.realnameStatus" :level="shop.level" :membership-active="shop.membershipActive" show-level show-membership /></view></view>
    <text class="player-bio">{{shop.bio||'这个玩家还没有填写个人简介。'}}</text>
    <view v-if="shop.shopStatus==='APPROVED'" class="shop-strip"><AppIcon name="bag" :size="17" /><view class="stack flex-1"><text class="bold">{{shop.shopName}}</text><text v-if="shop.shopIntro" class="tiny muted">{{shop.shopIntro}}</text></view><text class="shop-label">认证店铺</text></view>
    <view class="profile-metrics"><text>{{shop.completed}} 单成交</text><text>{{shop.followers}} 人关注</text></view>
    <view class="badge-showcase">
     <view class="row between"><text class="badge-heading">勋章</text><text v-if="!badgeLoading&&!badgeError&&badges.length" class="badge-count">{{badges.length}} 枚</text></view>
     <text v-if="badgeLoading" class="badge-status">勋章加载中…</text>
     <view v-else-if="badgeError" class="badge-failure"><text class="badge-status">勋章暂时加载失败</text><button class="ui-button badge-retry" @click="loadBadges()">重试</button></view>
     <RewardBadges v-else-if="badges.length" :items="badges" />
     <text v-else class="badge-status">暂无勋章</text>
    </view>
    <view class="profile-actions"><button v-if="!ownHome" class="ui-button btn outline" :disabled="following" @click="follow">{{shop.followed?'已关注':'＋ 关注'}}</button><button v-if="!ownHome" class="ui-button btn" @click="chatWith(shop.id)">联系玩家</button><button v-else class="ui-button btn outline" @click="go('account/index',{type:'profile'})">编辑个人资料</button></view>
   </view>
   <view class="pad public-listings"><view class="tabs"><button v-for="tab in tabs" :key="tab.kind" class="ui-button" :class="{selected:kind===tab.kind}" @click="selectKind(tab.kind)">{{tab.label}}</button></view><StateView :loading="listLoading" :error="listError" :count="items.length" :title="kind==='REQUEST'?'暂时没有公开求购':'暂时没有公开交易内容'" description="仅展示审核通过且当前公开的道具和求购" @retry="loadServices()" /><view class="service-grid section"><view v-for="item in items" :key="item.id" class="published-item"><text v-if="item.kind==='REQUEST'" class="request-label">求购</text><ServiceCard :item="item" /></view></view><button v-if="items.length<total" class="ui-button load-more" :disabled="listLoading" @click="more">{{listLoading?'加载中…':'查看更多'}}</button></view>
  </template>
 </AppShell>
</template>
<script setup>
import {ref,computed} from 'vue';import {onLoad,onShow,onUnload,onReachBottom} from '@dcloudio/uni-app';import AppShell from '../../components/AppShell.vue';import AppIcon from '../../components/AppIcon.vue';import GameArt from '../../components/GameArt.vue';import PlayerBadges from '../../components/PlayerBadges.vue';import ServiceCard from '../../components/ServiceCard.vue';import StateView from '../../components/StateView.vue';import RewardBadges from '../../components/RewardBadges.vue';import {loadConfig,session,request,requireLogin,chatWith,toast,go} from '../../lib/api';import {useList} from '../../lib/useList'
const badges=ref([]),badgeLoading=ref(false),badgeError=ref('');const id=ref(''),shop=ref(null),kind=ref(''),loading=ref(false),error=ref(''),following=ref(false),tabs=[{kind:'',label:'全部发布'},{kind:'SERVICE',label:'出售道具'},{kind:'REQUEST',label:'求购道具'}];let generation=0,badgeRequest=0
const ownHome=computed(()=>Number(session.user?.id)===Number(id.value));const {items,total,loading:listLoading,error:listError,load:loadServices,more}=useList('/boost/listings',()=>({kind:kind.value,seller:id.value}));onLoad(q=>{id.value=q.id});onShow(load);onUnload(()=>{generation++});onReachBottom(more)
async function load(){const current=++generation;loading.value=true;error.value='';shop.value=null;badges.value=[];badgeLoading.value=true;badgeError.value='';try{const result=await request('/boost/shops/'+id.value);if(current!==generation)return;shop.value=result;await Promise.all([loadServices(),loadBadges(current)])}catch(e){if(current===generation)error.value=e.message}finally{if(current===generation)loading.value=false}}
async function loadBadges(current=generation){const attempt=++badgeRequest,owner=id.value;badgeLoading.value=true;badgeError.value='';try{const config=await loadConfig();if(current!==generation||attempt!==badgeRequest)return;const result=config.rewardsEnabled?await request('/boost/rewards/badges/'+owner):[];if(current===generation&&attempt===badgeRequest)badges.value=result}catch(e){if(current===generation&&attempt===badgeRequest)badgeError.value=e.message}finally{if(current===generation&&attempt===badgeRequest)badgeLoading.value=false}}
function selectKind(value){kind.value=value;loadServices()}
async function follow(){if(!requireLogin()||following.value||!shop.value)return;const shown=shop.value,token=session.token;following.value=true;try{const followed=await request(`/boost/shops/${id.value}/follow`,'POST',{desired:!shown.followed});if(shop.value!==shown||token!==session.token)return;if(followed!==shown.followed)shown.followers+=followed?1:-1;shown.followed=followed}catch(e){if(token===session.token)toast(e.message)}finally{following.value=false}}
</script>
<style scoped>.player-home-head{background:#fff;padding:24px 16px 18px}.identity-row{align-items:flex-start;gap:14px}.player-name{font-size:23px;font-weight:750;line-height:1.3;overflow-wrap:anywhere}.province{font-size:11px;color:#83858c;margin:3px 0}.player-bio{display:block;margin-top:18px;line-height:1.7;font-size:13px;color:#555b62;white-space:pre-wrap;overflow-wrap:anywhere}.shop-strip{display:flex;gap:9px;align-items:center;background:#fff9dc;border:1px solid #f3e7b1;border-radius:10px;padding:12px;margin-top:16px}.shop-label{font-size:10px;color:#705817;flex-shrink:0}.profile-metrics{display:flex;flex-wrap:wrap;gap:16px;color:#757981;font-size:11px;margin:18px 0}.profile-actions{display:flex;gap:10px}.profile-actions .btn{flex:1}.badge-showcase{padding:12px 14px;margin-bottom:16px;border-radius:10px;background:#f7f8fa;min-height:72px;box-sizing:border-box}.badge-heading{font-size:13px;font-weight:650}.badge-count{font-size:11px;color:var(--muted)}.badge-status{display:block;padding-top:8px;font-size:12px;line-height:1.6;color:var(--muted)}.badge-failure{display:flex;align-items:center;justify-content:space-between;gap:8px}.badge-failure .badge-status{padding-top:0}.badge-retry{min-height:44px;min-width:44px;font-size:12px;color:#705817;text-align:center}.public-listings .tabs{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0;background:#fff;border-radius:10px;padding:6px 0;margin-bottom:12px}.public-listings .tabs .ui-button{display:flex;align-items:center;justify-content:center;min-width:0;min-height:44px;padding:0 4px;text-align:center;white-space:nowrap}.public-listings .tabs .ui-button.selected::after{top:auto;right:auto;margin:0;bottom:3px}.published-item{position:relative;min-width:0}.request-label{position:absolute;z-index:2;left:8px;top:8px;background:#ffe433;color:#171717;border-radius:5px;padding:3px 7px;font-size:11px;font-weight:700}</style>
